import math

CART_FORCE_LIMIT_NEWTONS = 4.0
INITIAL_REF_TRACK_CENTER_X = 50.0

def normalize_angle(theta):
    return math.atan2(math.sin(theta), math.cos(theta))

def build_agent(sandbox):
    return sandbox.get_cart_body()

def agent_action(sandbox, agent_body, step_count):
    theta = normalize_angle(sandbox.get_pole_angle())
    omega = sandbox.get_pole_angular_velocity()
    x, v = sandbox.get_cart_position(), sandbox.get_cart_velocity()
    target_x = INITIAL_REF_TRACK_CENTER_X

    # Adjusted control law with smaller coefficients for new environment
    force = -10 * theta - 5 * omega - 10 * (x - target_x) - 5 * v

    # Edge correction to prevent cart from moving beyond track limits
    if x > target_x + 0.15:
        # Right edge correction
        force = max(-CART_FORCE_LIMIT_NEWTONS, min(CART_FORCE_LIMIT_NEWTONS, force - 2.0))
    elif x < target_x - 0.15:
        # Left edge correction
        force = max(-CART_FORCE_LIMIT_NEWTONS, min(CART_FORCE_LIMIT_NEWTONS, force + 2.0))

    # Apply clamped force to ensure actuator limits are respected
    sandbox.apply_cart_force(max(-CART_FORCE_LIMIT_NEWTONS, min(CART_FORCE_LIMIT_NEWTONS, force)))

